  computed_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT pk_trust_score PRIMARY KEY (id),
  CONSTRAINT ck_trust_score_one_subject CHECK ((app_user_id IS NULL) <> (organisation_id IS NULL)),
  CONSTRAINT ck_trust_score_score_range CHECK (score >= 0 AND score <= 100),
  CONSTRAINT fk_trust_score_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_trust_score_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_trust_score_trust_band_id FOREIGN KEY (trust_band_id) REFERENCES trust_band (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_trust_score_app_user_id (app_user_id) WHERE app_user_id IS NOT NULL,
  UNIQUE INDEX uq_trust_score_organisation_id (organisation_id) WHERE organisation_id IS NOT NULL,
  INDEX idx_trust_score_trust_band_id_score (trust_band_id, score)
);
