  computed_at TIMESTAMPTZ NOT NULL,
  change_reason STRING(120) NOT NULL,
  CONSTRAINT pk_trust_score_history PRIMARY KEY (id),
  CONSTRAINT ck_trust_score_history_score_range CHECK (score >= 0 AND score <= 100),
  CONSTRAINT fk_trust_score_history_trust_score_id FOREIGN KEY (trust_score_id) REFERENCES trust_score (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_trust_score_history_trust_band_id FOREIGN KEY (trust_band_id) REFERENCES trust_band (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_trust_score_history_trust_score_id_computed_at (trust_score_id, computed_at DESC),
  INDEX idx_trust_score_history_trust_band_id (trust_band_id),
  INDEX idx_trust_score_history_computed_at (computed_at) USING HASH WITH (bucket_count = 16)
) WITH (ttl_expiration_expression = '(computed_at + INTERVAL ''2 years'')', ttl_job_cron = '@daily');
