  INDEX idx_fraud_signal_event_severity_id (event_severity_id),
  INDEX idx_fraud_signal_detected_at (detected_at) USING HASH WITH (bucket_count = 32)
) WITH (ttl_expiration_expression = '(detected_at + INTERVAL ''13 months'')', ttl_job_cron = '@daily');
