  CONSTRAINT fk_workforce_request_work_type_id FOREIGN KEY (work_type_id) REFERENCES work_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_workforce_request_work_country_id FOREIGN KEY (work_country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
