  po_number STRING(60),
  cost_centre STRING(60),
  work_country_id UUID,
  staffing_end_reason_id UUID,
  ended_at TIMESTAMPTZ,
  CONSTRAINT pk_staffing_assignment PRIMARY KEY (id),
  CONSTRAINT uq_staffing_assignment_id_client_organisation_id UNIQUE (id, client_organisation_id),
  CONSTRAINT ck_staffing_assignment_assignment_window CHECK (assignment_end_date IS NULL OR assignment_end_date >= assignment_start_date),
  CONSTRAINT ck_staffing_assignment_rates_positive CHECK (bill_rate >= 0 AND pay_rate >= 0),
  CONSTRAINT ck_staffing_assignment_end_reason_when_ended CHECK ((ended_at IS NULL) = (staffing_end_reason_id IS NULL)),
  CONSTRAINT ck_staffing_assignment_ot_multiplier CHECK (overtime_multiplier IS NULL OR overtime_multiplier >= 1),
