  CONSTRAINT fk_staffing_assignment_worker_candidate_profile_id FOREIGN KEY (worker_candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_staffing_assignment_workforce_request_id FOREIGN KEY (workforce_request_id) REFERENCES workforce_request (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_staffing_assignment_vendor_submission_id FOREIGN KEY (vendor_submission_id) REFERENCES vendor_submission (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_staffing_assignment_remote_workforce_team_id FOREIGN KEY (remote_workforce_team_id) REFERENCES remote_workforce_team (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_staffing_assignment_supervisor_app_user_id FOREIGN KEY (supervisor_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_staffing_assignment_staffing_engagement_type_id FOREIGN KEY (staffing_engagement_type_id) REFERENCES staffing_engagement_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_staffing_assignment_staffing_assignment_status_id FOREIGN KEY (staffing_assignment_status_id) REFERENCES staffing_assignment_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_staffing_assignment_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_staffing_assignment_salary_period_id FOREIGN KEY (salary_period_id) REFERENCES salary_period (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_staffing_assignment_work_country_id FOREIGN KEY (work_country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_staffing_assignment_staffing_end_reason_id FOREIGN KEY (staffing_end_reason_id) REFERENCES staffing_end_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_staffing_assignment_vendor_submission_id (vendor_submission_id) WHERE vendor_submission_id IS NOT NULL AND deleted_at IS NULL,
  INDEX idx_staffing_assignment_client_organisation_id_staffing_assignment_status_id (client_organisation_id, staffing_assignment_status_id),
  INDEX idx_staffing_assignment_agency_organisation_id_staffing_assignment_status_id (agency_organisation_id, staffing_assignment_status_id),
  INDEX idx_staffing_assignment_worker_candidate_profile_id_assignment_start_date (worker_candidate_profile_id, assignment_start_date DESC),
  INDEX idx_staffing_assignment_workforce_request_id (workforce_request_id),
  INDEX idx_staffing_assignment_remote_workforce_team_id (remote_workforce_team_id),
  INDEX idx_staffing_assignment_supervisor_app_user_id (supervisor_app_user_id),
  INDEX idx_staffing_assignment_staffing_engagement_type_id (staffing_engagement_type_id),
  INDEX idx_staffing_assignment_salary_period_id (salary_period_id),
  INDEX idx_staffing_assignment_work_country_id (work_country_id),
  INDEX idx_staffing_assignment_staffing_end_reason_id (staffing_end_reason_id),
  INDEX idx_staffing_assignment_currency_id (currency_id),
  INDEX idx_staffing_assignment_staffing_assignment_status_id (staffing_assignment_status_id)
