CREATE TABLE IF NOT EXISTS timesheet (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  staffing_assignment_id UUID NOT NULL,
  period_start_date DATE NOT NULL,
  period_end_date DATE NOT NULL,
  timesheet_status_id UUID NOT NULL,
  total_hours DECIMAL(7,2) NOT NULL DEFAULT 0,
  submission_no INT2 NOT NULL DEFAULT 1,
  submitted_at TIMESTAMPTZ,
  submitted_by_app_user_id UUID,
  locked_at TIMESTAMPTZ,
  CONSTRAINT pk_timesheet PRIMARY KEY (id),
  CONSTRAINT ck_timesheet_period_window CHECK (period_end_date >= period_start_date),
  CONSTRAINT ck_timesheet_hours_nonneg CHECK (total_hours >= 0),
  CONSTRAINT ck_timesheet_submission_positive CHECK (submission_no >= 1),
  CONSTRAINT fk_timesheet_staffing_assignment_id FOREIGN KEY (staffing_assignment_id) REFERENCES staffing_assignment (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_timesheet_timesheet_status_id FOREIGN KEY (timesheet_status_id) REFERENCES timesheet_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_timesheet_submitted_by_app_user_id FOREIGN KEY (submitted_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_timesheet_staffing_assignment_id_period_start_date (staffing_assignment_id, period_start_date) WHERE deleted_at IS NULL,
  INDEX idx_timesheet_timesheet_status_id_period_end_date (timesheet_status_id, period_end_date),
  INDEX idx_timesheet_submitted_by_app_user_id (submitted_by_app_user_id)
);
