CREATE TABLE IF NOT EXISTS timesheet_approval (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  timesheet_id UUID NOT NULL,
