  submission_no INT2 NOT NULL,
  approval_level INT2 NOT NULL DEFAULT 1,
  approval_status_id UUID NOT NULL,
  decided_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  decision_note STRING(500),
  CONSTRAINT pk_timesheet_approval PRIMARY KEY (id),
  CONSTRAINT uq_timesheet_approval_timesheet_id_submission_no_approval_level UNIQUE (timesheet_id, submission_no, approval_level),
  CONSTRAINT ck_timesheet_approval_level_range CHECK (approval_level BETWEEN 1 AND 5),
  CONSTRAINT fk_timesheet_approval_timesheet_id FOREIGN KEY (timesheet_id) REFERENCES timesheet (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_timesheet_approval_approver_app_user_id FOREIGN KEY (approver_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_timesheet_approval_approval_status_id FOREIGN KEY (approval_status_id) REFERENCES approval_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_timesheet_approval_approver_app_user_id_decided_at (approver_app_user_id, decided_at DESC),
  INDEX idx_timesheet_approval_approval_status_id (approval_status_id)
);
