CREATE TABLE IF NOT EXISTS timesheet_entry (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  timesheet_id UUID NOT NULL,
  work_date DATE NOT NULL,
  hours DECIMAL(5,2) NOT NULL,
  timesheet_entry_kind_id UUID NOT NULL,
  is_billable BOOL NOT NULL DEFAULT true,
  task_description STRING(300),
  CONSTRAINT pk_timesheet_entry PRIMARY KEY (id),
  CONSTRAINT ck_timesheet_entry_hours_range CHECK (hours > 0 AND hours <= 24),
  CONSTRAINT fk_timesheet_entry_timesheet_id FOREIGN KEY (timesheet_id) REFERENCES timesheet (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_timesheet_entry_timesheet_entry_kind_id FOREIGN KEY (timesheet_entry_kind_id) REFERENCES timesheet_entry_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_timesheet_entry_timesheet_id_work_date (timesheet_id, work_date),
  INDEX idx_timesheet_entry_timesheet_entry_kind_id (timesheet_entry_kind_id),
  INDEX idx_timesheet_entry_work_date (work_date) USING HASH WITH (bucket_count = 16)
);
