  INDEX idx_onboarding_document_submission_onboarding_document_request_id_submitted_at (onboarding_document_request_id, submitted_at DESC),
  INDEX idx_onboarding_document_submission_review_approval_status_id (review_approval_status_id),
  INDEX idx_onboarding_document_submission_reviewed_by_app_user_id (reviewed_by_app_user_id)
);
-- @@
CREATE TABLE IF NOT EXISTS onboarding_plan (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  organisation_id UUID NOT NULL,
  joining_id UUID NOT NULL,
  candidate_profile_id UUID NOT NULL,
  onboarding_plan_template_id UUID,
  onboarding_plan_status_id UUID NOT NULL,
  hiring_manager_app_user_id UUID,
  buddy_app_user_id UUID,
  plan_start_date DATE NOT NULL,
  plan_end_date DATE,
  completion_percent DECIMAL(5,2) NOT NULL DEFAULT 0,
  completed_at TIMESTAMPTZ,
  CONSTRAINT pk_onboarding_plan PRIMARY KEY (id),
  CONSTRAINT uq_onboarding_plan_id_organisation_id UNIQUE (id, organisation_id),
  CONSTRAINT ck_onboarding_plan_completion_percent_range CHECK (completion_percent IS NULL OR (completion_percent >= 0 AND completion_percent <= 100)),
  CONSTRAINT ck_onboarding_plan_dates CHECK (plan_end_date IS NULL OR plan_end_date >= plan_start_date),
  CONSTRAINT fk_onboarding_plan_joining_id FOREIGN KEY (joining_id) REFERENCES joining (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_onboarding_plan_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_onboarding_plan_onboarding_plan_template_id FOREIGN KEY (onboarding_plan_template_id) REFERENCES onboarding_plan_template (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_onboarding_plan_onboarding_plan_status_id FOREIGN KEY (onboarding_plan_status_id) REFERENCES onboarding_plan_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_onboarding_plan_hiring_manager_app_user_id FOREIGN KEY (hiring_manager_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_onboarding_plan_buddy_app_user_id FOREIGN KEY (buddy_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_onboarding_plan_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_onboarding_plan_joining_id (joining_id) WHERE deleted_at IS NULL,
  INDEX idx_onboarding_plan_organisation_id_onboarding_plan_status_id (organisation_id, onboarding_plan_status_id),
  INDEX idx_onboarding_plan_candidate_profile_id (candidate_profile_id),
  INDEX idx_onboarding_plan_onboarding_plan_template_id (onboarding_plan_template_id),
  INDEX idx_onboarding_plan_onboarding_plan_status_id (onboarding_plan_status_id),
  INDEX idx_onboarding_plan_hiring_manager_app_user_id (hiring_manager_app_user_id),
  INDEX idx_onboarding_plan_buddy_app_user_id (buddy_app_user_id)
);
-- @@
CREATE TABLE IF NOT EXISTS onboarding_plan_task (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  onboarding_plan_id UUID NOT NULL,
  organisation_id UUID NOT NULL,
  onboarding_plan_template_task_id UUID,
  legacy_onboarding_task_id UUID,
  sequence_no INT2 NOT NULL,
  title STRING(200) NOT NULL,
  onboarding_task_type_id UUID NOT NULL,
  onboarding_task_status_id UUID NOT NULL,
  due_date DATE,
  is_required BOOL NOT NULL DEFAULT true,
  completed_at TIMESTAMPTZ,
  completed_by_app_user_id UUID,
  CONSTRAINT pk_onboarding_plan_task PRIMARY KEY (id),
  CONSTRAINT ck_onboarding_plan_task_seq_positive CHECK (sequence_no >= 1),
  CONSTRAINT ck_onboarding_plan_task_completed_pair CHECK (completed_at IS NOT NULL OR completed_by_app_user_id IS NULL),
  CONSTRAINT fk_onboarding_plan_task_onboarding_plan_template_task_id FOREIGN KEY (onboarding_plan_template_task_id) REFERENCES onboarding_plan_template_task (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_onboarding_plan_task_legacy_onboarding_task_id FOREIGN KEY (legacy_onboarding_task_id) REFERENCES onboarding_task (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_onboarding_plan_task_onboarding_task_type_id FOREIGN KEY (onboarding_task_type_id) REFERENCES onboarding_task_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_onboarding_plan_task_onboarding_task_status_id FOREIGN KEY (onboarding_task_status_id) REFERENCES onboarding_task_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_onboarding_plan_task_completed_by_app_user_id FOREIGN KEY (completed_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_onboarding_plan_task_plan_tenant FOREIGN KEY (onboarding_plan_id, organisation_id) REFERENCES onboarding_plan (id, organisation_id) ON DELETE CASCADE ON UPDATE RESTRICT,
  UNIQUE INDEX uq_onboarding_plan_task_onboarding_plan_id_sequence_no (onboarding_plan_id, sequence_no) WHERE deleted_at IS NULL,
  INDEX idx_onboarding_plan_task_onboarding_task_status_id_due_date (onboarding_task_status_id, due_date) WHERE completed_at IS NULL,
  INDEX idx_onboarding_plan_task_onboarding_plan_template_task_id (onboarding_plan_template_task_id),
  INDEX idx_onboarding_plan_task_legacy_onboarding_task_id (legacy_onboarding_task_id),
  INDEX idx_onboarding_plan_task_onboarding_task_type_id (onboarding_task_type_id),
  INDEX idx_onboarding_plan_task_completed_by_app_user_id (completed_by_app_user_id)
);
-- @@
CREATE TABLE IF NOT EXISTS onboarding_task_assignment (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  onboarding_plan_task_id UUID NOT NULL,
  assignee_app_user_id UUID NOT NULL,
  onboarding_assignee_role_id UUID NOT NULL,
  is_primary BOOL NOT NULL DEFAULT false,
  assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  acknowledged_at TIMESTAMPTZ,
  reminder_count INT2 NOT NULL DEFAULT 0,
  last_reminded_at TIMESTAMPTZ,
  CONSTRAINT pk_onboarding_task_assignment PRIMARY KEY (id),
  CONSTRAINT uq_onboarding_task_assignment_onboarding_plan_task_id_assignee_app_user_id UNIQUE (onboarding_plan_task_id, assignee_app_user_id),
  CONSTRAINT ck_onboarding_task_assignment_reminders_nonneg CHECK (reminder_count >= 0),
  CONSTRAINT fk_onboarding_task_assignment_onboarding_plan_task_id FOREIGN KEY (onboarding_plan_task_id) REFERENCES onboarding_plan_task (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_onboarding_task_assignment_assignee_app_user_id FOREIGN KEY (assignee_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_onboarding_task_assignment_onboarding_assignee_role_id FOREIGN KEY (onboarding_assignee_role_id) REFERENCES onboarding_assignee_role (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_onboarding_task_assignment_onboarding_plan_task_id (onboarding_plan_task_id) WHERE is_primary,
  INDEX idx_onboarding_task_assignment_assignee_app_user_id_assigned_at (assignee_app_user_id, assigned_at DESC),
  INDEX idx_onboarding_task_assignment_onboarding_assignee_role_id (onboarding_assignee_role_id)
);
-- @@
CREATE TABLE IF NOT EXISTS reference_check_request (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  organisation_id UUID NOT NULL,
  candidate_profile_id UUID NOT NULL,
  job_application_id UUID,
  referee_name STRING(150) NOT NULL,
  referee_email STRING(254),
  referee_phone STRING(16),
  referee_phone_country_id UUID,
  referee_company STRING(200),
  referee_relationship_id UUID NOT NULL,
  reference_check_status_id UUID NOT NULL,
  access_token_hash STRING(128) NOT NULL,
  user_consent_id UUID,
  requested_by_app_user_id UUID NOT NULL,
  sent_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ NOT NULL,
  reminder_count INT2 NOT NULL DEFAULT 0,
  CONSTRAINT pk_reference_check_request PRIMARY KEY (id),
  CONSTRAINT ck_reference_check_request_referee_email_lower CHECK (referee_email IS NULL OR referee_email = lower(referee_email)),
  CONSTRAINT ck_reference_check_request_referee_phone_e164 CHECK (referee_phone IS NULL OR referee_phone ~ '^\+[1-9][0-9]{6,14}$'),
  CONSTRAINT ck_reference_check_request_referee_contact_present CHECK (referee_email IS NOT NULL OR referee_phone IS NOT NULL),
  CONSTRAINT ck_reference_check_request_expiry_after_sent CHECK (sent_at IS NULL OR expires_at > sent_at),
  CONSTRAINT fk_reference_check_request_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_reference_check_request_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_reference_check_request_job_application_id FOREIGN KEY (job_application_id) REFERENCES job_application (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_reference_check_request_referee_phone_country_id FOREIGN KEY (referee_phone_country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_reference_check_request_referee_relationship_id FOREIGN KEY (referee_relationship_id) REFERENCES referee_relationship (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_reference_check_request_reference_check_status_id FOREIGN KEY (reference_check_status_id) REFERENCES reference_check_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_reference_check_request_user_consent_id FOREIGN KEY (user_consent_id) REFERENCES user_consent (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_reference_check_request_requested_by_app_user_id FOREIGN KEY (requested_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_reference_check_request_access_token_hash (access_token_hash) WHERE deleted_at IS NULL,
  INDEX idx_reference_check_request_candidate_profile_id_reference_check_status_id (candidate_profile_id, reference_check_status_id),
  INDEX idx_reference_check_request_organisation_id (organisation_id),
  INDEX idx_reference_check_request_job_application_id (job_application_id),
  INDEX idx_reference_check_request_user_consent_id (user_consent_id),
  INDEX idx_reference_check_request_requested_by_app_user_id (requested_by_app_user_id),
  INDEX idx_reference_check_request_referee_phone_country_id (referee_phone_country_id),
  INDEX idx_reference_check_request_referee_relationship_id (referee_relationship_id),
  INDEX idx_reference_check_request_reference_check_status_id (reference_check_status_id)
);
-- @@
CREATE TABLE IF NOT EXISTS reference_check_response (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  reference_check_request_id UUID NOT NULL,
  submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  overall_rating INT2,
  would_rehire BOOL NOT NULL DEFAULT false,
  tenure_confirmed BOOL NOT NULL DEFAULT false,
  answers_encrypted BYTES NOT NULL,
  responder_ip INET,
  CONSTRAINT pk_reference_check_response PRIMARY KEY (id),
  CONSTRAINT uq_reference_check_response_reference_check_request_id UNIQUE (reference_check_request_id),
  CONSTRAINT ck_reference_check_response_rating_range CHECK (overall_rating IS NULL OR overall_rating BETWEEN 1 AND 5),
  CONSTRAINT fk_reference_check_response_reference_check_request_id FOREIGN KEY (reference_check_request_id) REFERENCES reference_check_request (id) ON DELETE CASCADE ON UPDATE RESTRICT
);
